function lib(s: { id: string; name: string; credit: string; roles: string[]; triggers: string[]; purpose: string; instructions: string; acceptance: string[] }): SkillSpec {
  return {
    id: s.id,
    version: "1.0.0",
    roles: s.roles,
    triggers: s.triggers,
    enabled: true,
    source: "builtin",
    purpose: s.purpose,
    instructions: s.instructions,
    allowedTools: ["list_files", "read_file", "search_code", "apply_patch", "replace_file", "create_file", "run_script", "find_image", "task_complete", "report_blocked"],
    inputSchema: "Task",
    outputSchema: "ChangedPaths",
    policies: { network: "denied", filesystem: "governed_write" },
    acceptance: s.acceptance,
    tests: [],
    changelog: [{ version: "1.0.0", date: "2026-10-06", note: `From AgenticSkills: ${s.credit}` }],
  };
}

